schemas.declaration:
pgTable("addon_entitlements", {
  addonId: uuid("addon_id").notNull().references(() => addonsTable.id),
  key: text("key").notNull().references(() => entitlementDefinitionsTable.key),
  value: jsonb("value").$type<boolean | string>().notNull(),
}, (t) => [
  primaryKey({ columns: [t.addonId, t.key] }),
])

pgTable("asset_catalog", {
  id: text("id").primaryKey(),
  symbol: text("symbol").notNull(),
  name: text("name").notNull(),
})

pgTable("asset_network_catalog", {
  id: text("id").primaryKey(),
  assetId: text("asset_id").notNull().references(() => assetsTable.id),
  networkId: text("network_id").notNull().references(() => networksTable.id),
})

pgTable("entitlement_definitions", {
  key: text("key").primaryKey(),
  label: text("label").notNull(),
  kind: text("kind").notNull(),
  valueType: text("value_type").notNull(),
}, () => [
  check("entitlement_definition_kind_type", sql`(kind = 'feature' AND value_type = 'boolean') OR (kind = 'limit' AND value_type IN ('integer','decimal'))`),
])

pgTable("network_catalog", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  testnet: boolean("testnet").notNull().default(true),
})

pgTable("notification_events", {
  id: uuid("id").primaryKey().defaultRandom(),
  tenantId: uuid("tenant_id").notNull().references(() => tenantsTable.id),
  channel: text("channel").notNull(),
  payload: jsonb("payload").notNull().default({}),
  status: text("status").notNull().default("sandbox_queued"),
  environment: text("environment").notNull().default("sandbox"),
}, () => [
  check("notifications_sandbox_only", sql`environment = 'sandbox'`),
])

pgTable("plan_entitlements", {
  planId: uuid("plan_id").notNull().references(() => plansTable.id),
  key: text("key").notNull().references(() => entitlementDefinitionsTable.key),
  value: jsonb("value").$type<boolean | string>().notNull(),
}, (t) => [
  primaryKey({ columns: [t.planId, t.key] }),
])

pgTable("platform_admins", {
  clerkUserId: text("clerk_user_id").primaryKey(),
  active: boolean("active").notNull().default(true),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
})

pgTable("tenant_addons", {
  tenantId: uuid("tenant_id").notNull().references(() => tenantsTable.id),
  addonId: uuid("addon_id").notNull().references(() => addonsTable.id),
}, (t) => [
  primaryKey({ columns: [t.tenantId, t.addonId] }),
])

pgTable("tenant_asset_networks", {
  tenantId: uuid("tenant_id").notNull().references(() => tenantsTable.id),
  assetNetworkId: text("asset_network_id").notNull().references(() => assetNetworksTable.id),
}, (t) => [
  primaryKey({ columns: [t.tenantId, t.assetNetworkId] }),
])

pgTable("tenant_configuration", {
  tenantId: uuid("tenant_id").primaryKey().references(() => tenantsTable.id),
  environment: text("environment").notNull().default("sandbox"),
  exchangeEnabled: boolean("exchange_enabled").notNull().default(false),
  paymentsEnabled: boolean("payments_enabled").notNull().default(false),
  allowGuestCheckout: boolean("allow_guest_checkout").notNull().default(false),
}, () => [
  check("configuration_sandbox_only", sql`environment = 'sandbox'`),
])

pgTable("tenant_domains", {
  tenantId: uuid("tenant_id").primaryKey().references(() => tenantsTable.id),
  domain: text("domain").notNull().unique(),
  status: text("status").notNull().default("unverified"),
  verificationToken: text("verification_token"),
  verifiedAt: timestamp("verified_at", { withTimezone: true }),
}, () => [
  check("domains_valid_status", sql`status IN ('unverified', 'verified')`),
])

pgTable("tenant_entitlement_overrides", {
  tenantId: uuid("tenant_id").notNull().references(() => tenantsTable.id),
  key: text("key").notNull().references(() => entitlementDefinitionsTable.key),
  value: jsonb("value").$type<boolean | string>().notNull(),
  reason: text("reason").notNull(),
}, (t) => [
  primaryKey({ columns: [t.tenantId, t.key] }),
])

pgTable("tenant_modules", {
  tenantId: uuid("tenant_id").notNull().references(() => tenantsTable.id),
  moduleKey: text("module_key").notNull().references(() => modulesTable.key),
  enabled: boolean("enabled").notNull().default(false),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  primaryKey({ columns: [t.tenantId, t.moduleKey] }),
])

pgTable("tenant_payment_methods", {
  id: uuid("id").primaryKey().defaultRandom(),
  tenantId: uuid("tenant_id").notNull().references(() => tenantsTable.id),
  label: text("label").notNull(),
  environment: text("environment").notNull().default("sandbox"),
}, () => [
  check("payment_methods_sandbox", sql`environment = 'sandbox'`),
])

pgTable("tenant_product_configuration", {
  tenantId: uuid("tenant_id").notNull().references(() => tenantsTable.id),
  moduleKey: text("module_key").notNull().references(() => modulesTable.key),
  configuration: jsonb("configuration").notNull().default({}),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  primaryKey({ columns: [t.tenantId, t.moduleKey] }),
  check("product_configuration_object", sql`jsonb_typeof(configuration) = 'object'`),
])

pgTable("tenant_subscriptions", {
  tenantId: uuid("tenant_id").primaryKey().references(() => tenantsTable.id),
  planId: uuid("plan_id").notNull().references(() => plansTable.id),
  status: text("status").notNull().default("active"),
  resumeStatus: text("resume_status").notNull().default("draft"),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, () => [
  check("subscription_status", sql`status IN ('active','suspended')`),
  check("subscription_resume_status", sql`resume_status IN ('draft','active')`),
])

pgTable("tenant_usage_counters", {
  tenantId: uuid("tenant_id").notNull().references(() => tenantsTable.id),
  key: text("key").notNull().references(() => entitlementDefinitionsTable.key),
  period: text("period").notNull(),
  used: numeric("used", { precision: 36, scale: 18 }).notNull().default("0"),
}, (t) => [
  primaryKey({ columns: [t.tenantId, t.key, t.period] }),
  check("usage_nonnegative", sql`used >= 0`),
  check("usage_month_format", sql`period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'`),
])

pgTable("wallet_configurations", {
  id: uuid("id").primaryKey().defaultRandom(),
  tenantId: uuid("tenant_id").notNull().references(() => tenantsTable.id),
  assetNetworkId: text("asset_network_id").notNull(),
  strategy: text("strategy").notNull().default("sandbox"),
  environment: text("environment").notNull().default("sandbox"),
}, (t) => [
  foreignKey({ columns: [t.tenantId, t.assetNetworkId], foreignColumns: [tenantAssetsNetworksTable.tenantId, tenantAssetsNetworksTable.assetNetworkId] }),
  check("wallets_sandbox_only", sql`environment = 'sandbox' AND strategy = 'sandbox'`),
])

pgTable("webhook_endpoints", {
  id: uuid("id").primaryKey().defaultRandom(),
  tenantId: uuid("tenant_id").notNull().references(() => tenantsTable.id),
  url: text("url").notNull(),
  label: text("label").notNull().default("Webhook"),
  enabled: boolean("enabled").notNull().default(false),
  environment: text("environment").notNull().default("sandbox"),
}, () => [
  check("webhooks_sandbox_only", sql`environment = 'sandbox'`),
])
